// BAD: SQL Injection via string concatenation (vulnerable)
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class InsecureLoginServlet extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) {
        String user = request.getParameter("username");
        String pass = request.getParameter("password");

        // DANGEROUS: Improper Java API usage (Statement with concatenated input) — vulnerable
        String sql = "SELECT id FROM users WHERE username = '" + user + "' AND password = '" + pass + "'";

        try (Connection conn = DriverManager.getConnection("jdbc:yourdb", "user", "pwd");
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {

            if (rs.next()) {
                // Auth success (but an attacker could bypass via ' OR '1'='1)
            } else {
                // Auth failed
            }
        } catch (SQLException e) {
            // Handle error
        }
    }
}
***
/* GOOD: Use PreparedStatement with parameters to prevent SQL injection */
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class SecureLoginServlet extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) {
        String user = request.getParameter("username");
        String pass = request.getParameter("password");

        // SAFE: Proper Java API usage with parameterized query
        String sql = "SELECT id FROM users WHERE username = ? AND password = ?";

        try (Connection conn = DriverManager.getConnection("jdbc:yourdb", "user", "pwd");
             PreparedStatement ps = conn.prepareStatement(sql)) {

            ps.setString(1, user);
            ps.setString(2, pass);
            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    // Auth success
                } else {
                    // Auth failed
                }
            }
        } catch (SQLException e) {
            // Handle error
        }
    }
}

