// BAD: Using string concatenation to build SQL queries (SQL Injection vulnerable)
import java.sql.*;
import javax.servlet.http.*;

public class UserControllerBad extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) {
        String username = request.getParameter("username"); // untrusted input
        String password = request.getParameter("password"); // untrusted input

        // vulnerable: attacker can inject SQL via username or password
        String sql = "SELECT id, role FROM users WHERE username = '" + username + "' AND password = '" + password + "'";

        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/app", "appuser", "apppass");
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {

            if (rs.next()) {
                // logged in (but query itself is unsafe)
            }
        } catch (SQLException e) {
            // improper error handling: leaking details to client (another issue)
            e.printStackTrace();
        }
    }
}
***
/*
GOOD: Use PreparedStatement with parameter binding to prevent SQL Injection.
Also avoid leaking errors and use constant-time password checks if verifying hashes in app code.
*/
import java.sql.*;
import javax.servlet.http.*;

public class UserControllerGood extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) {
        String username = request.getParameter("username");
        String password = request.getParameter("password");

        String sql = "SELECT id, role FROM users WHERE username = ? AND password = ?";

        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/app", "appuser", "apppass");
             PreparedStatement ps = conn.prepareStatement(sql)) {

            // Safe parameter binding prevents injection
            ps.setString(1, username);
            ps.setString(2, password); // In practice, store and compare password hashes

            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    // logged in safely (assuming proper password hashing is implemented)
                }
            }
        } catch (SQLException e) {
            // Log internally; do not expose details to clients
            log("Database error", e);
        }
    }
}

